-- 1132: PCB calculators -- bare-board fabrication (imaging, lamination, drilling, plating, solder mask, legend, finish, profile, test) as real database calculators.
--
-- GENERATED by scripts/generate-pcb-calculators-migration.ts from
-- src/modules/bom-items/costing/pcb/calculators/pcb-calculators.json.
-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- PCB was staged (reference data 2026-PCB: 108 variables, the stack-up tables, the sourced consumables, process times and yields; 104 USA
-- machines and their India twins, 13 laminates) but had no cost engine: its catalog processes had no calculator, and a part whose Process
-- is PCB was not costed. These are the calculators of its fabrication steps: each catalog process times one board from the memory/PCBA
-- variables and its machine's own specs; the board material, a core built from the reference, the drilling consumables, the solder mask, a
-- plated metal, a test fixture and the fabrication yield are helpers the engine runs per board, which no operation maps to.
--
-- This migration creates one global calculator per spec entry (inputs are the
-- values the cost engine seeds, each shown with its source in the calculation
-- trace; calculated fields are the formulas the engine evaluates, it holds
-- none) and links every PCB catalog operation it computes to its
-- calculator in process_calculator_mappings.
--
-- Requires migration 804 (calculators.retired_at).
-- Self-contained, idempotent, post-checked.

BEGIN;

-- PCB - Surface Preparation
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$PCB - Surface Preparation$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$PCB - Surface Preparation$q$, 'process', 'single', false, true, true, $q$Brushes and cleans each panel before photo resist, once per pass (every inner-layer core and the outer layers). The prep line is a conveyor: the panel and its spacing (defaultConveyorPanelSpacingLength) through the line at its conveyor speed, panels side by side as its usable width takes them. memory/PCBA gives the Chemcut / SCUBBEX / Unibloc lines a width but no speed, so the speed is the photo-resist line's the panels go on to (engine).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Brushes and cleans each panel before photo resist, once per pass (every inner-layer core and the outer layers). The prep line is a conveyor: the panel and its spacing (defaultConveyorPanelSpacingLength) through the line at its conveyor speed, panels side by side as its usable width takes them. memory/PCBA gives the Chemcut / SCUBBEX / Unibloc lines a width but no speed, so the speed is the photo-resist line's the panels go on to (engine).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Boards Per Panel$q$, $q$Boards Per Panel$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Panel Length$q$, $q$Panel Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Panel Width$q$, $q$Panel Width (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Passes$q$, $q$Passes$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Conveyor Speed$q$, $q$Conveyor Speed (mm/s)$q$, $q$number$q$, $q$mm/s$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Panel Spacing$q$, $q$Panel Spacing (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Usable Width$q$, $q$Usable Width (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 7, true),
    (v_id, $q$Width Spacing$q$, $q$Width Spacing (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 8, true),
