    (v_id, $q$Cycle Time Adjustment$q$, $q$Cycle Time Adjustment$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 10, true),
    (v_id, $q$Panel Time$q$, $q$Panel Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$({Panel Length} + {Panel Spacing}) / {Conveyor Speed} / {Panels Across}$q$, 11, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Panel Time} * {Passes} / {Boards Per Panel} * {Cycle Time Adjustment}$q$, 12, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$PCB - Surface Preparation$q$, is_active = is_active OR machine_class IS NOT NULL
  WHERE process_group = $q$PCB$q$ AND operation IN ($q$Surface Preparation$q$);
END
