  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$PCB - Bed of nails fixture$q$, 'process', 'single', false, true, true, $q$A bed-of-nails test fixture: its build (defaultProberAssemblyTime at the tester's machine and labour rate) and its parts (consumables.csv bed_of_nails_fixture_usd, midpoint).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$A bed-of-nails test fixture: its build (defaultProberAssemblyTime at the tester's machine and labour rate) and its parts (consumables.csv bed_of_nails_fixture_usd, midpoint).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Build Time$q$, $q$Build Time (h)$q$, $q$number$q$, $q$h$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Hourly Rate$q$, $q$Hourly Rate (USD/h)$q$, $q$number$q$, $q$USD/h$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Fixture Price$q$, $q$Fixture Price (USD)$q$, $q$number$q$, $q$USD$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Fixture Cost$q$, $q$Fixture Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Build Time} * {Hourly Rate} + {Fixture Price}$q$, 4, false);
END
$calc$;

-- PCB - Fabrication yield
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$PCB - Fabrication yield$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$PCB - Fabrication yield$q$, 'process', 'single', false, true, true, $q$The boards scrapped in fabrication, charged on the good ones: the board's cost x (1 / first-pass yield - 1), the yield by layer count (memory/PCBA/yield.csv fab_yield_pct, midpoint of the rows for the nearest layer count).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$The boards scrapped in fabrication, charged on the good ones: the board's cost x (1 / first-pass yield - 1), the yield by layer count (memory/PCBA/yield.csv fab_yield_pct, midpoint of the rows for the nearest layer count).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Board Cost$q$, $q$Board Cost (USD)$q$, $q$number$q$, $q$USD$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Yield$q$, $q$Yield (%)$q$, $q$number$q$, $q$%$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Scrap Cost$q$, $q$Scrap Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Board Cost} * (100 / {Yield} - 1)$q$, 3, false);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$PCB - Surface Preparation$q$, 12, 1),
    ($q$PCB - Apply Photo Resist$q$, 10, 1),
    ($q$PCB - Photolithography$q$, 11, 1),
    ($q$PCB - DES$q$, 13, 1),
    ($q$PCB - Dissolve Unexposed Photo Resist$q$, 13, 1),
    ($q$PCB - SES$q$, 13, 1),
    ($q$PCB - Automated Optical Inspection$q$, 12, 1),
    ($q$PCB - Bench Operation$q$, 11, 1),
    ($q$PCB - Oven Cure Layers$q$, 9, 1),
    ($q$PCB - Drill Registration Holes$q$, 14, 1),
    ($q$PCB - Drill Circuit Holes$q$, 14, 1),
    ($q$PCB - Laser Drill Vias$q$, 10, 1),
    ($q$PCB - Desmear and Plate Through Holes$q$, 13, 1),
    ($q$PCB - Copper Plate and Tin Coat$q$, 15, 1),
    ($q$PCB - Plug Vias$q$, 8, 1),
    ($q$PCB - Cure Plugged Vias$q$, 8, 1),
    ($q$PCB - Wet Film Solder Mask$q$, 9, 1),
    ($q$PCB - Tack Dry Solder Mask$q$, 20, 1),
    ($q$PCB - Film Imaging$q$, 11, 1),
    ($q$PCB - Develop Solder Mask$q$, 13, 1),
    ($q$PCB - Cure Solder Mask$q$, 20, 1),
    ($q$PCB - Screen Printing$q$, 8, 1),
    ($q$PCB - Silkscreen Cure$q$, 8, 1),
    ($q$PCB - Hot Air Solder Leveling$q$, 7, 1),
    ($q$PCB - Electroless Nickel Immersion Gold$q$, 10, 1),
    ($q$PCB - Organic Solderability Preservative$q$, 13, 1),
    ($q$PCB - Router$q$, 13, 1),
    ($q$PCB - Stamp$q$, 8, 1),
    ($q$PCB - Flying Probe$q$, 10, 1),
    ($q$PCB - Bed of Nails$q$, 8, 1),
    ($q$PCB - Automated Vision Inspection$q$, 7, 1),
    ($q$PCB - Board material$q$, 11, 0),
    ($q$PCB - Core price$q$, 6, 0),
    ($q$PCB - Drilling consumables$q$, 4, 0),
    ($q$PCB - Solder mask material$q$, 8, 0),
    ($q$PCB - Plating metal$q$, 6, 0),
    ($q$PCB - Bed of nails fixture$q$, 4, 0),
    ($q$PCB - Fabrication yield$q$, 3, 0)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$PCB$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1132: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
